INSERT INTO alternatives (id,original_product_id,alternative_product_id,similarity_type,feature_match,price_advantage,usage_scenario,recommendation_reason,functional_difference,verification_status,last_verified_at,source_ids) VALUES ('elevenlabs--cartesia','elevenlabs','cartesia','shared-function','["text-to-speech","voice-cloning"]','Use the current matched monthly plans below; the entry fee difference is not a guarantee of workload savings.','Character-based TTS with instant voice cloning on paid plans.','Both advertise TTS and paid-plan instant cloning. Compare monthly fees and model-specific character allowances.','Voice library, cloning and output characteristics differ; no quality score is assigned.','verified','2026-10-30','["elevenlabs-pricing","cartesia-pricing"]') ON CONFLICT(id) DO UPDATE SET original_product_id=excluded.original_product_id,alternative_product_id=excluded.alternative_product_id,similarity_type=excluded.similarity_type,feature_match=excluded.feature_match,price_advantage=excluded.price_advantage,usage_scenario=excluded.usage_scenario,recommendation_reason=excluded.recommendation_reason,functional_difference=excluded.functional_difference,verification_status=excluded.verification_status,last_verified_at=excluded.last_verified_at,source_ids=excluded.source_ids;
INSERT INTO alternatives (id,original_product_id,alternative_product_id,similarity_type,feature_match,price_advantage,usage_scenario,recommendation_reason,functional_difference,verification_status,last_verified_at,source_ids) VALUES ('elevenlabs--google-cloud-tts','elevenlabs','google-cloud-tts','shared-function','["text-to-speech"]','Pay-as-you-go with a free allowance; compare only character-based stock-voice workloads.','Standard stock-voice speech synthesis through an API.','Shared text-to-speech function; Google publishes a character allowance and usage rate.','This offer is for Standard stock voices, not a substitute for ElevenLabs voice cloning.','verified','2026-10-30','["elevenlabs-pricing","google-tts"]') ON CONFLICT(id) DO UPDATE SET original_product_id=excluded.original_product_id,alternative_product_id=excluded.alternative_product_id,similarity_type=excluded.similarity_type,feature_match=excluded.feature_match,price_advantage=excluded.price_advantage,usage_scenario=excluded.usage_scenario,recommendation_reason=excluded.recommendation_reason,functional_difference=excluded.functional_difference,verification_status=excluded.verification_status,last_verified_at=excluded.last_verified_at,source_ids=excluded.source_ids;
INSERT INTO alternatives (id,original_product_id,alternative_product_id,similarity_type,feature_match,price_advantage,usage_scenario,recommendation_reason,functional_difference,verification_status,last_verified_at,source_ids) VALUES ('cartesia--elevenlabs','cartesia','elevenlabs','shared-function','["text-to-speech","voice-cloning"]','A free TTS plan is available; compare paid-plan allowances and feature restrictions separately.','Explore another voice library and cloning workflow.','Shared TTS and cloning functions; compare allowances for the selected model.','This direction is explicitly curated and is not asserted to be cheaper.','verified','2026-10-30','["cartesia-pricing","elevenlabs-pricing"]') ON CONFLICT(id) DO UPDATE SET original_product_id=excluded.original_product_id,alternative_product_id=excluded.alternative_product_id,similarity_type=excluded.similarity_type,feature_match=excluded.feature_match,price_advantage=excluded.price_advantage,usage_scenario=excluded.usage_scenario,recommendation_reason=excluded.recommendation_reason,functional_difference=excluded.functional_difference,verification_status=excluded.verification_status,last_verified_at=excluded.last_verified_at,source_ids=excluded.source_ids;
INSERT INTO alternatives (id,original_product_id,alternative_product_id,similarity_type,feature_match,price_advantage,usage_scenario,recommendation_reason,functional_difference,verification_status,last_verified_at,source_ids) VALUES ('suno--stable-audio','suno','stable-audio','shared-function','["text-to-music"]','Free allowance available; paid monthly and annual prices must not be directly ranked.','Instrumental music or audio generation.','Both provide text-to-music generation; Stable Audio offers a free monthly credit allowance.','Instrumental/audio workflow is not equivalent to Suno vocal songs, editing or download rights.','verified','2026-10-30','["suno-pricing","suno-v6","stable-pricing"]') ON CONFLICT(id) DO UPDATE SET original_product_id=excluded.original_product_id,alternative_product_id=excluded.alternative_product_id,similarity_type=excluded.similarity_type,feature_match=excluded.feature_match,price_advantage=excluded.price_advantage,usage_scenario=excluded.usage_scenario,recommendation_reason=excluded.recommendation_reason,functional_difference=excluded.functional_difference,verification_status=excluded.verification_status,last_verified_at=excluded.last_verified_at,source_ids=excluded.source_ids;
