INSERT INTO catalog_revisions (id,sync_log_id,catalog_json) VALUES ('initial-2026-10-30','initial-2026-10-30','{"version":1,"updatedAt":"2026-11-02","sources":[{"id":"midjourney-plans","url":"https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans","title":"Midjourney plan comparison","checkedAt":"2026-10-30","notes":"Basic $10/month or $96/year. GPU time is not a fixed image quota. No per-image price inferred."},{"id":"replicate-flux","url":"https://replicate.com/black-forest-labs/flux-schnell","title":"Replicate FLUX.1 schnell","checkedAt":"2026-10-30","notes":"Browser-verified pricing: $3 per 1,000 output images. Apache-2.0 model; API available."},{"id":"runway-plans","url":"https://runway.com/pricing","title":"Runway subscriptions","checkedAt":"2026-10-30","notes":"Standard $15 monthly or $144 annually; 625 credits/month. Free 125 credits are once-only. API billing is separate."},{"id":"runway-credits","url":"https://help.runwayml.com/hc/en-us/articles/15124877443219-How-do-credits-work","title":"Runway credit usage","checkedAt":"2026-10-30","notes":"Gen-4.5 uses 12 credits/second. Published example supports 5- or 10-second generations."},{"id":"runway-api","url":"https://dev.runwayml.com/pricing","title":"Runway API pricing","checkedAt":"2026-10-30","notes":"Gen-4 Turbo API: $0.05/second. Separate from web subscription credits."},{"id":"replicate-kling","url":"https://replicate.com/kwaivgi/kling-v2.1","title":"Replicate Kling v2.1","checkedAt":"2026-10-30","notes":"Browser-verified: Standard 720p $0.05/second; Pro 1080p $0.09/second. Image input; 5 or 10 seconds. Not Kling web subscription pricing."},{"id":"elevenlabs-pricing","url":"https://elevenlabs.io/pricing","title":"ElevenLabs pricing and FAQ","checkedAt":"2026-10-30","notes":"Regular Starter $6/month, 30,000 credits; Free 10,000. Multilingual v2 uses one credit/character. Intro offers excluded."},{"id":"google-tts","url":"https://cloud.google.com/text-to-speech/pricing","title":"Google Cloud TTS pricing","checkedAt":"2026-10-30","notes":"Standard voices: 4 million free characters/month, then $4/million. Billing account required; SSML and whitespace counting rules apply."},{"id":"cartesia-pricing","url":"https://www.cartesia.ai/pricing","title":"Cartesia pricing","checkedAt":"2026-10-30","notes":"Free 20,000 credits/month; Pro $5/month includes 100,000. One TTS character equals one credit; minute conversion is approximate and not used."},{"id":"suno-pricing","url":"https://suno.com/pricing","title":"Suno pricing","checkedAt":"2026-10-30","notes":"Pro annual $96 ($8/month equivalent), 2,500 credits/month. Free 50 credits/day, no commercial rights or song downloads. Current plan limits apply."},{"id":"suno-v6","url":"https://help.suno.com/en/articles/13924481","title":"Suno v6 FAQ","checkedAt":"2026-10-30","notes":"Official v6 FAQ specifies 10 credits for a generation producing two songs. Applies only to this action/model, not editing or other features."},{"id":"stable-pricing","url":"https://stableaudio.com/pricing","title":"Stable Audio pricing","checkedAt":"2026-10-30","notes":"Browser-verified: free 50 credits/month; paid entry $12/month for 660 credits. Approximate generation counts not treated as exact tariffs."}],"products":[{"id":"midjourney","slug":"midjourney","name":"Midjourney","category":"image","provider":"Midjourney","website":"https://www.midjourney.com","summary":"Image creation with subscriptions measured in GPU time.","summaryZh":"以 GPU 时间计量的订阅制图片创作工具。","features":["text-to-image","image-editing"],"models":["Midjourney"],"api":null,"status":"verified","verifiedAt":"2026-10-30","sourceIds":["midjourney-plans"],"plans":[{"id":"mj-basic","name":"Basic","amount":10,"billing":"monthly","currency":"USD","pricingModels":["monthly"],"freeAllowance":"","commercial":null,"limits":["200 fast GPU minutes/month; image count varies."],"sourceIds":["midjourney-plans"],"verifiedAt":"2026-10-30","status":"verified","components":[{"id":"mj-gpu","unit":"image","unitSize":1,"rate":null,"included":null,"creditAllowance":null,"creditsPerUnit":null,"allowancePeriod":"month","model":"","resolution":"","quality":"","durations":[],"maxDuration":null,"note":"GPU time cannot be converted to a fixed image count."}],"features":["text-to-image"]},{"id":"mj-basic-year","name":"Basic annual","amount":96,"billing":"annual","currency":"USD","pricingModels":["annual"],"freeAllowance":"","commercial":null,"limits":["Full year paid upfront; 200 fast GPU minutes each month."],"sourceIds":["midjourney-plans"],"verifiedAt":"2026-10-30","status":"verified","components":[],"features":["text-to-image"]}]},{"id":"flux-schnell","slug":"flux-schnell","name":"FLUX.1 schnell on Replicate","category":"image","provider":"Replicate / Black Forest Labs","website":"https://replicate.com/black-forest-labs/flux-schnell","summary":"Text-to-image API billed per output image.","summaryZh":"按输出图片计费的文生图 API。","features":["text-to-image"],"models":["FLUX.1 schnell"],"api":true,"status":"verified","verifiedAt":"2026-10-30","sourceIds":["replicate-flux"],"plans":[{"id":"flux-payg","name":"Output images","amount":0,"billing":"pay-as-you-go","currency":"USD","pricingModels":["pay-as-you-go"],"freeAllowance":"","commercial":true,"limits":["API workflow; output style and controls differ from Midjourney."],"sourceIds":["replicate-flux"],"verifiedAt":"2026-10-30","status":"verified","components":[{"id":"flux-image","unit":"image","unitSize":1000,"rate":3,"included":null,"creditAllowance":null,"creditsPerUnit":null,"allowancePeriod":"month","model":"FLUX.1 schnell","resolution":"","quality":"","durations":[],"maxDuration":null,"note":"Published per 1,000 output images; counts outputs, not requests."}],"features":["text-to-image"]}]},{"id":"runway","slug":"runway","name":"Runway","category":"video","provider":"Runway","website":"https://runway.com","summary":"Video creation workspace and separately billed generation API.","summaryZh":"视频创作工作区及独立计费的